#!/usr/bin/env node
// Emits the Lore test-command `list` shape: a single JSON array of
// {id, name, file} objects, one per test, and nothing else on stdout.
// Jest cannot resolve test names without executing them - there is no
// dry-run - so the suite is run once with --json written to a temp file and
// progress sent to stderr, keeping stdout pure.
// The id is "<repo-relative-file>::<full test name>" - stable across runs,
// and exactly what the run command's {selector} splits back apart.
import {execFileSync} from 'node:child_process';
import {readFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, relative} from 'node:path';
import process from 'node:process';

const reportFile = join(tmpdir(), `hal-engine-jest-report-${process.pid}.json`);

try {
  execFileSync('npx', ['jest', '--json', `--outputFile=${reportFile}`], {
    cwd: process.cwd(),
    stdio: ['ignore', 'ignore', 'inherit'],
    // The suite runs as ESM; jest needs the flag in every spawn, not just npm test.
    env: {...process.env, NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --experimental-vm-modules`.trim()},
  });
} catch {
  // A failing test still produces a full report, and listing must not depend
  // on the suite being green. An unreadable report below is the real failure.
}

let report;

try {
  report = JSON.parse(readFileSync(reportFile, 'utf8'));
} catch (error) {
  process.stderr.write(`jest produced no readable report at ${reportFile}: ${error.message}\n`);
  process.exit(1);
} finally {
  rmSync(reportFile, {force: true});
}

const tests = report.testResults.flatMap(suite => {
  const file = relative(process.cwd(), suite.name);

  return suite.assertionResults.map(assertion => ({
    id: `${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
  }));
});

process.stdout.write(`${JSON.stringify(tests)}\n`);

  return content;
};

const extractAnchors = (source) =>
  [...source.matchAll(ANCHOR)].map((match) => ({ path: match[1], line: Number(match[2]) }));

const CONTENTLESS = /^[)\]}>,;]*$/;

// Only test files are held to the declaration check below; a citation into a
// workflow, a config or package.json is a supported target with no such shape.
const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;
const TEST_DECL = /^\s*(?:[fx]?it|[fx]?describe|test)\s*[.(`]/;

const rottenReason = (anchor, specDir) => {
  const testPath = normalize(join(specDir, anchor.path));
  const working = workingFile(testPath);

  if (working === null) {
    return `${testPath} does not exist in the working tree`;
  }
  const target = working.split("\n")[anchor.line - 1];

  if (target === undefined) {
    return `#L${anchor.line} is beyond the end of ${testPath}`;
  }

  if (CONTENTLESS.test(target.trim())) {
    return `#L${anchor.line} lands on a blank or closing line`;
  }

  if (TEST_FILE.test(testPath) && !TEST_DECL.test(target)) {
    return `#L${anchor.line} is not an it/test/describe declaration in ${testPath}`;
  }

  return null;
};

const sameAnchorPaths = (a, b) =>
  a.length === b.length && a.every((anchor, index) => anchor.path === b[index].path);

const CONTEXT_RADIUS = 4;

const contextScore = (baseLines, workingLines, baselineLine, candidateLine) => {
  let score = 0;

  for (let offset = -CONTEXT_RADIUS; offset <= CONTEXT_RADIUS; offset += 1) {
    if (offset === 0) {
      continue;
    }

    if (shape(baseLines[baselineLine - 1 + offset]) === shape(workingLines[candidateLine - 1 + offset])) {
      score += 1;
    }
  }

  return score;
};

// Lines are compared by shape, not text: a formatter changes quotes and
// spacing without moving anything, and that must not read as drift. An
// out-of-range line stays undefined so it never matches a real one.
const shape = (line) =>
  line === undefined ? undefined : line.replace(/["`]/g, "'").replace(/\s+/g, "");

